basic_single_field.code:
{{#groupBy products field="category" as |groups|}}
  {{#each groups as |group|}}
    <h2>{{group.key.category}} ({{group.count}} items)</h2>
    {{#each group.items as |product|}}
      <p>{{product.name}} — ${{numberFormat product.price "0.00"}}</p>
    {{/each}}
  {{/each}}
{{/groupBy}}

nested_field.code:
{{#groupBy orders field="shipping.method" as |groups|}}
  {{#each groups as |group|}}
    <h3>{{group.key.shipping.method}}</h3>
    {{#each group.items as |order|}}{{order.id}}{{/each}}
  {{/each}}
{{/groupBy}}

multi_field.code:
{{#groupBy items field="shippingMethod,estimatedDate" as |groups|}}
  {{#each groups as |group|}}
    <h3>{{group.key.shippingMethod}} — {{group.key.estimatedDate}}</h3>
    {{#each group.items as |item|}}{{item.name}}{{/each}}
  {{/each}}
{{/groupBy}}

with_catalog_collection.code:
{{#catalogCollection "AllProducts" as |items|}}
  {{#groupBy items field="category" as |groups|}}
    {{#each groups as |group|}}
      <h2>{{group.key.category}}</h2>
      {{#each group.items as |product|}}
        <img src="{{product.imageUrl}}" alt="{{product.name}}" width="200">
        <h3>{{product.name}}</h3>
        <p>{{product.description}}</p>
        <strong>${{numberFormat product.price "0.00"}}</strong>
      {{/each}}
    {{/each}}
  {{/groupBy}}
{{/catalogCollection}}

rei_order_confirmation.code:
{{#sortBy xmldata.ShipTos.ShipTo field="LineItems.ItemFirstPromisedDate" order="asc" as |sorted|}}
{{#groupBy sorted field="LineItems.ItemShippingMethod,LineItems.ItemFirstPromisedDate" as |groups|}}
{{#each groups as |group|}}
  <h3>{{group.key.LineItems.ItemShippingMethod}}
      — Arrives {{dateFormat group.key.LineItems.ItemFirstPromisedDate "MMM dd, yyyy"}}</h3>
  {{#sortBy group.items field="LineItems.ItemPrice" order="desc" as |sortedItems|}}
  {{#each sortedItems as |item|}}
    {{item.LineItems.ItemName}} Qty: {{item.LineItems.ItemQuantity}} ${{item.LineItems.ItemPrice}}
  {{/each}}
  {{/sortBy}}
{{/each}}
{{/groupBy}}
{{/sortBy}}

basic_price_sort.code:
{{#catalogCollection "AllProducts" as |items|}}
  {{#sortBy items field="price" order="asc" as |sorted|}}
    {{#each sorted as |product|}}
      {{product.name}} — ${{numberFormat product.price "0.00"}}
    {{/each}}
  {{/sortBy}}
{{/catalogCollection}}

multi_field_sort.code:
{{#sortBy items field="priority,name" order="desc" as |sorted|}}
  {{#each sorted as |item|}}{{item.name}} (priority {{item.priority}}){{/each}}
{{/sortBy}}

sort_then_group.code:
{{#sortBy items field="deliveryDate" order="asc" as |sorted|}}
  {{#groupBy sorted field="deliveryDate" as |groups|}}
    {{#each groups as |group|}}
      <h3>Arriving {{group.key.deliveryDate}} ({{group.count}} items)</h3>
      {{#each group.items as |item|}}{{item.name}}{{/each}}
    {{/each}}
  {{/groupBy}}
{{/sortBy}}

sort_within_groups.code:
{{#groupBy items field="shippingMethod" as |groups|}}
  {{#each groups as |group|}}
    <h3>{{group.key.shippingMethod}}</h3>
    {{#sortBy group.items field="price" order="asc" as |sorted|}}
      {{#each sorted as |p|}}
        {{p.name}} — ${{numberFormat p.price "0.00"}}
      {{/each}}
    {{/sortBy}}
  {{/each}}
{{/groupBy}}

